function validate([watchedVideos, friends, id, level]) {
  const n = watchedVideos.length;
  if (n < 2 || n > 100) return 'There must be 2 to 100 people.';
  if (friends.length !== n) return 'watchedVideos and friends must have the same length.';
  for (const list of watchedVideos) {
    if (list.length < 1 || list.length > 100) return 'Each person watched 1 to 100 videos.';
    if (list.some(v => typeof v !== 'string' || v.length < 1 || v.length > 8)) return 'Each video name has 1 to 8 characters.';
  }
  const sets = friends.map(f => new Set(f));
  for (let i = 0; i < n; i++) {
    if (friends[i].length >= n) return 'Each friends list has fewer than n entries.';
    for (const j of friends[i]) {
      if (!Number.isInteger(j) || j < 0 || j >= n) return 'Friend ids are between 0 and n - 1.';
      if (!sets[j].has(i)) return 'Friendships must go both ways.';
    }
  }
  if (!Number.isInteger(id) || id < 0 || id >= n) return 'id is between 0 and n - 1.';
  if (!Number.isInteger(level) || level < 1 || level >= n) return 'level is between 1 and n - 1.';
  return null;
}

