function watchedVideosByFriends(watchedVideos, friends, id, level) {
  const visited = new Array(friends.length).fill(false);
  visited[id] = true;
  let queue = [id];

  for (let step = 0; step < level && queue.length > 0; step++) {
    const next = [];
    for (const person of queue) {
      for (const friend of friends[person]) {
        if (!visited[friend]) {
          visited[friend] = true;
          next.push(friend);
        }
      }
    }
    queue = next;
  }

  const count = new Map();
  for (const person of queue) {
    for (const video of watchedVideos[person]) {
      count.set(video, (count.get(video) || 0) + 1);
    }
  }

  const videos = [...count.keys()];
  videos.sort((a, b) => count.get(a) - count.get(b) || (a < b ? -1 : 1));
  return videos;
}

