function watchedVideosByFriends(watchedVideos, friends, id, level) {
  const n = friends.length;
  // Shortest distances by repeated relaxation until nothing changes.
  const dist = new Array(n).fill(Infinity);
  dist[id] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let u = 0; u < n; u++) {
      if (dist[u] === Infinity) continue;
      for (const v of friends[u]) {
        if (dist[u] + 1 < dist[v]) { dist[v] = dist[u] + 1; changed = true; }
      }
    }
  }
  const tally = {};
  for (let p = 0; p < n; p++) {
    if (dist[p] !== level) continue;
    for (const name of watchedVideos[p]) tally[name] = (tally[name] ?? 0) + 1;
  }
  const pairs = Object.entries(tally);
  // Insertion sort by (count, name).
  for (let i = 1; i < pairs.length; i++) {
    for (let j = i; j > 0; j--) {
      const [na, ca] = pairs[j - 1], [nb, cb] = pairs[j];
      const before = cb < ca || (cb === ca && nb < na);
      if (!before) break;
      [pairs[j - 1], pairs[j]] = [pairs[j], pairs[j - 1]];
    }
  }
  return pairs.map(p => p[0]);
}

