function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(80, 100) : int(2, 8);
  const adj = Array.from({ length: n }, () => new Set());
  const link = (a, b) => { if (a !== b) { adj[a].add(b); adj[b].add(a); } };
  if (large) {
    // A random tree with a few extra edges keeps the graph deep enough for several levels.
    for (let v = 1; v < n; v++) if (rand() < 0.95) link(v, int(Math.max(0, v - 6), v - 1));
    for (let e = int(0, 30); e > 0; e--) link(int(0, n - 1), int(0, n - 1));
  } else {
    const p = rand() * 0.6;
    for (let a = 0; a < n; a++) for (let b = a + 1; b < n; b++) if (rand() < p) link(a, b);
  }
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz' : (rand() < 0.3 ? 'abAB' : 'abcd');
  const word = () => { let s = ''; const len = int(1, 2); for (let k = 0; k < len; k++) s += letters[int(0, letters.length - 1)]; return s; };
  const watchedVideos = Array.from({ length: n }, () => Array.from({ length: large ? int(20, 60) : int(1, 4) }, word));
  const friends = adj.map(s => [...s].sort(() => rand() - 0.5));
  const id = int(0, n - 1);
  const level = large ? int(1, Math.min(n - 1, 12)) : int(1, n - 1);
  return [watchedVideos, friends, id, level];
}
